// The Google Sheets node emits one item per row plus a row_number field.
// Keep the FIRST row that has no Status yet AND clears minRating, so the
// update node at the end can mark exactly that row done.
const cfg = $('Config').first().json;
const minRating = Number(cfg.minRating);
const floor = Number.isFinite(minRating) ? minRating : 4;
const isEmpty = (v) => v === undefined || v === null || String(v).trim() === '';
const num = (v) => {
  const n = Number(String(v == null ? '' : v).replace(',', '.').replace(/[^0-9.]/g, ''));
  return Number.isFinite(n) ? n : NaN;
};

// The sheet read runs with alwaysOutputData, so a header-only sheet arrives
// here as a single blank placeholder item instead of nothing at all. Dropping
// blank items keeps this node running (and reporting) on an empty sheet.
const rows = $input.all()
  .map((i) => i.json)
  .filter((r) => r && typeof r === "object" && Object.keys(r).some((k) => k !== "row_number" && !isEmpty(r[k])));

if (!rows.length) {
  return [{
    json: {
      found: false,
      source: 'sheet',
      checked: 0,
      pending: 0,
      minRating: floor,
      reason: 'The sheet has no data rows yet. Add a review under the header row (Reviewer, Rating, ReviewText).',
    },
  }];
}

const pending = rows.filter((r) => isEmpty(r.Status));
const row = pending.find((r) => {
  const n = num(r.Rating);
  return Number.isFinite(n) && n >= floor;
});

if (!row) {
  return [{
    json: {
      found: false,
      source: 'sheet',
      checked: rows.length,
      pending: pending.length,
      minRating: floor,
      reason: pending.length
        ? 'Every pending row is rated below minRating (' + floor + '). Lower minRating in Config or add a higher-rated review.'
        : 'No row with an empty Status column. Add fresh review rows to the sheet.',
    },
  }];
}

const text = String(row.ReviewText || '').trim();
const reviewer = String(row.Reviewer || '').trim();
if (!text || !reviewer) {
  throw new Error('Row ' + row.row_number + ' is missing Reviewer or ReviewText. Fill both columns, or put anything in Status to skip the row.');
}

return [{
  json: {
    found: true,
    source: 'sheet',
    reviewer,
    rating: num(row.Rating),
    text,
    product: String(row.Product || '').trim(),
    imageUrl: String(row.ImageUrl || '').trim(),
    rowNumber: row.row_number,
    reviewId: null,
    checked: rows.length,
  },
}];

// Judge.me answers { reviews: [ { id, rating, body, reviewer: { name }, ... } ] }.
// Field names follow the public Judge.me reviews API; anything missing
// degrades to an empty string instead of throwing, and a bad HTTP status ends
// the run with a friendly "nothing to render" instead of an error.
const cfg = $('Config').first().json;
const minRating = Number(cfg.minRating);
const floor = Number.isFinite(minRating) ? minRating : 4;
const staticData = $getWorkflowStaticData('global');
const seen = Array.isArray(staticData.seenReviewIds) ? staticData.seenReviewIds : [];

// The fetch node ships with fullResponse on, so an item looks like
// { statusCode, headers, body }. Accept the raw Judge.me body too, in case
// someone turns fullResponse off - otherwise a perfectly good response would
// be reported as "unreachable".
const res = ($input.first() && $input.first().json) || {};
const enveloped = Object.prototype.hasOwnProperty.call(res, 'statusCode') || Object.prototype.hasOwnProperty.call(res, 'body');
const body = (enveloped ? res.body : res) || {};
const status = enveloped
  ? Number(res.statusCode)
  : (Array.isArray(body.reviews) ? 200 : NaN);

const stop = (reason) => [{ json: { found: false, source: "judgeme", checked: 0, reason } }];

if (!Number.isFinite(status) || status === 0) {
  return stop('Judge.me was unreachable. Check judgemeShop and judgemeToken in Config.');
}
if (status === 401 || status === 403) {
  return stop('Judge.me rejected the token (HTTP ' + status + '). Re-copy judgemeToken from the Judge.me dashboard.');
}
if (status !== 200) {
  return stop('Judge.me answered HTTP ' + status + '.');
}

const list = Array.isArray(body.reviews) ? body.reviews : [];
if (!list.length) return stop('Judge.me returned no reviews for this shop.');

const reviewText = (r) => String((r && (r.body || r.title)) || '').trim();
// A review that is hidden, unpublished or flagged as spam must never become a
// public testimonial. Missing flags mean "fine" - Judge.me only sends them
// when they are set.
const isPublic = (r) => r.hidden !== true && r.published !== false && String(r.curated || '').toLowerCase() !== 'spam';

const unseen = list
  .filter((r) => Number(r.rating) >= floor)
  .filter((r) => seen.indexOf(String(r.id)) === -1);
const visible = unseen.filter(isPublic);
// A star-only review has nothing to put on screen. Skipping it HERE is what
// keeps the queue moving: it is never written to seenReviewIds (that only
// happens after a successful render), so if it were picked it would be picked
// again on every future run and the run would fail every time.
const candidates = visible.filter((r) => reviewText(r).length > 0);

if (!candidates.length) {
  const skippedEmpty = visible.length - candidates.length;
  const skippedHidden = unseen.length - visible.length;
  const extra = (skippedEmpty ? ' Skipped ' + skippedEmpty + ' star-only review(s) with no written text.' : '')
    + (skippedHidden ? ' Skipped ' + skippedHidden + ' hidden/unpublished review(s).' : '');
  return stop('No usable unseen review at ' + floor + ' stars or better. Judge.me returned ' + list.length + ' review(s).' + extra);
}

const r = candidates[0];
const reviewerName = (r.reviewer && (r.reviewer.name || r.reviewer.display_name))
  || r.reviewer_name
  || 'A customer';

// The id is only remembered AFTER a successful render (see Run summary), so a
// failed render retries the same review on the next run.
return [{
  json: {
    found: true,
    source: 'judgeme',
    reviewer: String(reviewerName).trim(),
    rating: Number(r.rating),
    text: reviewText(r),
    product: String(r.product_title || r.product_handle || '').trim(),
    imageUrl: String((Array.isArray(r.pictures) && r.pictures[0] && (r.pictures[0].urls ? r.pictures[0].urls.original : r.pictures[0].url)) || '').trim(),
    rowNumber: null,
    reviewId: String(r.id),
    checked: list.length,
  },
}];

// No review is waiting. This is a normal, successful outcome - not an error.
const picked = $input.first().json;
return [{
  json: {
    rendered: false,
    source: picked.source,
    reason: picked.reason || 'Nothing to render.',
    reviewsChecked: picked.checked,
  },
}];

// One place where untrusted review text is made safe and predictable before
// it reaches the trimmer and the design: collapse whitespace, drop any HTML a
// review platform let through, normalise curly quotes and ellipses to plain
// ASCII so the wrap estimate and the trimmer count real characters, and clamp the
// rating to 1..5. (The builder HTML-escapes on top of this.)
const cfg = $('Config').first().json;
const row = $input.first().json;

const strip = (s) => String(s == null ? "" : s)
  .replace(/<br\s*\/?>/gi, " ")
  .replace(/<[^>]*>/g, " ")
  .replace(/&nbsp;/gi, " ")
  .replace(/&amp;/gi, "&")
  .replace(/[\u2018\u2019\u201A\u201B]/g, "'")
  .replace(/[\u201C\u201D\u201E\u201F]/g, '"')
  .replace(/\u2026/g, "...")
  .replace(/\s+/g, " ")
  .trim();

const text = strip(row.text);
const reviewer = strip(row.reviewer);
if (!text) throw new Error("The picked review has no text.");
if (!reviewer) throw new Error("The picked review has no reviewer name.");

const rating = Number(row.rating);
if (!Number.isFinite(rating) || rating <= 0) {
  throw new Error("The picked review has no usable rating (got \"" + String(row.rating) + "\"). Use a number 1-5.");
}

const imageUrl = String(row.imageUrl || "").trim();

return [{
  json: {
    ...row,
    reviewer,
    text,
    rating: Math.min(5, Math.max(1, rating)),
    product: strip(row.product),
    // Only http(s) media reaches the renderer; anything else is treated as
    // "no image" and the hook scene re-balances itself.
    imageUrl: /^https?:\/\//i.test(imageUrl) ? imageUrl : "",
    minRating: Number(cfg.minRating) || 4,
  },
}];

// The music bed is optional. An unreachable URL, an HTTP error or a file over
// the plan's audio cap renders the video WITHOUT music instead of failing the
// run - a missing soundtrack is a much smaller problem than a missing video.
const cfg = $('Config').first().json;
const review = $('Clean review text').first().json;
const res = $input.first().json;

const maxBytes = Number(cfg.maxMusicBytes) || 5242880;
const url = String(cfg.musicUrl || '').trim();

let musicUrl = url;
let reason = null;
let bytes = null;

if (!url) {
  musicUrl = '';
  reason = 'musicUrl is empty in Config';
} else {
  const status = Number(res && res.statusCode);
  const headers = (res && res.headers) || {};
  const len = Number(headers['content-length'] || headers['Content-Length'] || 0);
  bytes = Number.isFinite(len) && len > 0 ? len : null;
  if (!Number.isFinite(status) || status === 0) {
    musicUrl = '';
    reason = 'the music URL was unreachable';
  } else if (status >= 400) {
    musicUrl = '';
    reason = 'the music URL answered HTTP ' + status;
  } else if (bytes && bytes > maxBytes) {
    musicUrl = '';
    reason = 'the music file is ' + Math.round(bytes / 1024) + ' KB, over the ' + Math.round(maxBytes / 1024) + ' KB cap';
  }
}

return [{ json: { ...review, musicUrl, musicBytes: bytes, musicSkippedReason: reason } }];

// The LLM may only SELECT a span of the customer's own words - it must never
// write new ones. Guard: strip everything but letters and digits from both the
// answer and the original; if the answer is not contained in the original, or
// is over budget, or the call failed, fall back to the same rule-based trim the
// default (LLM-free) path uses. A testimonial that puts words in a customer's
// mouth is worse than no testimonial.
const cfg = $('Config').first().json;
const row = $('Music guard').first().json;
const res = $input.first().json;

const maxChars = Math.max(60, Math.min(400, Number(cfg.maxQuoteChars) || 220));
const normalise = (s) => String(s == null ? '' : s).replace(/\s+/g, ' ').trim();

function ruleTrim(text, max) {
  const t = normalise(text);
  if (!t) return { quote: "", truncated: false };
  if (t.length <= max) return { quote: t, truncated: false };
  const parts = t.match(/[^.!?\u2026]+[.!?\u2026]*\s*/g) || [t];
  let acc = '';
  for (let i = 0; i < parts.length; i += 1) {
    if ((acc + parts[i]).trim().length > max) break;
    acc += parts[i];
  }
  acc = acc.trim();
  if (acc.length >= Math.floor(max * 0.6)) return { quote: acc, truncated: true };
  let cut = t.slice(0, max - 1);
  const sp = cut.lastIndexOf(' ');
  if (sp > max * 0.5) cut = cut.slice(0, sp);
  return { quote: cut.replace(/[\s,;:.!?\-\u2013\u2014]+$/, "") + "\u2026", truncated: true };
}

const original = normalise(row.text);
const fold = (s) => String(s).toLowerCase().replace(/[^a-z0-9]+/g, "");

let quote = null;
let usedLlm = false;
let fallbackReason = null;

try {
  const content = res.choices[0].message.content;
  const parsed = typeof content === 'string' ? JSON.parse(content) : content;
  const candidate = normalise(parsed.quote);
  if (!candidate) fallbackReason = 'the model returned an empty quote';
  else if (candidate.length > maxChars) fallbackReason = 'the model went over the ' + maxChars + '-character budget';
  else if (fold(original).indexOf(fold(candidate)) === -1) fallbackReason = 'the model reworded the review instead of quoting it';
  else { quote = candidate; usedLlm = true; }
} catch (e) {
  fallbackReason = 'the model call failed or returned non-JSON';
}

let truncated = false;
if (!quote) {
  const res2 = ruleTrim(original, maxChars);
  quote = res2.quote;
  truncated = res2.truncated;
} else {
  truncated = quote.length < original.length;
}

return [{
  json: {
    ...row,
    quote,
    trimmedBy: usedLlm ? 'llm' : 'rule',
    llmFallbackReason: fallbackReason,
    truncated,
    originalChars: original.length,
  },
}];

// Rule-based quote trimming — the DEFAULT path (useLlm is false out of the box,
// so the template needs no LLM key at all).
//
// Long reviews do not fit on a reel. The rule: keep whole sentences while they
// fit inside maxQuoteChars; if not even the first sentence fits, cut on a word
// boundary and mark the cut with an ellipsis. Nothing is ever added, reworded
// or paraphrased — the words on screen are the customer's own.
const cfg = $('Config').first().json;
const row = $input.first().json;

const maxChars = Math.max(60, Math.min(400, Number(cfg.maxQuoteChars) || 220));

const normalise = (s) => String(s == null ? '' : s)
  .replace(/\r/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

function trimQuote(text, max) {
  const t = normalise(text);
  if (!t) return { quote: '', truncated: false };
  if (t.length <= max) return { quote: t, truncated: false };

  // Longest run of WHOLE sentences that still fits.
  const parts = t.match(/[^.!?…]+[.!?…]*\s*/g) || [t];
  let acc = '';
  for (let i = 0; i < parts.length; i += 1) {
    if ((acc + parts[i]).trim().length > max) break;
    acc += parts[i];
  }
  acc = acc.trim();
  // A single short sentence would waste the frame — only keep the sentence cut
  // when it fills most of the budget.
  if (acc.length >= Math.floor(max * 0.6)) return { quote: acc, truncated: true };

  let cut = t.slice(0, max - 1);
  const sp = cut.lastIndexOf(' ');
  if (sp > max * 0.5) cut = cut.slice(0, sp);
  return { quote: cut.replace(/[\s,;:.!?\-–—]+$/, '') + '…', truncated: true };
}

const original = normalise(row.text);
const res = trimQuote(original, maxChars);
if (!res.quote) {
  throw new Error('The review has no text. Fill ReviewText (sheet) or check the Judge.me response.');
}

return [{
  json: Object.assign({}, row, {
    quote: res.quote,
    trimmedBy: 'rule',
    truncated: res.truncated,
    originalChars: original.length,
  }),
}];

// === buildProject — identical to the frame-reviewed standalone builder ===
// Turns ONE normalised review into a three-scene 1080x1920 testimonial reel.
//
//   scene 1  hook   — product photo as a full-bleed hero under a scrim (or a
//                     designed ink gradient when the review carries no image),
//                     brand, kicker, honest star row, rating label
//   scene 2  quote  — paper card: ghost quotation glyph, the quote in serif
//                     italic, accent rule, monogram + reviewer + verified tag
//   scene 3  cta    — product name / hook line, CTA pill, store domain, brand
//
// The star row is DRAWN from the real rating (rounded to the nearest whole
// star, clamped 1..5): filled stars for the score, outlined stars for the rest.
// A 4-star review renders four stars. Nothing here can inflate a rating.
//
// RENDERER NOTE: `resize` on a media element is resolved against the PROJECT
// canvas, not the element's own box — it is only safe on full-bleed layers.
// Inset imagery would be stretched, so this design never insets a photo.
function buildProject(config, data) {
  const cfg = config || {};
  const clean = function (v) { return String(v == null ? '' : v).replace(/\s+/g, ' ').trim(); };
  const esc = function (s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  };
  const round = function (n) { return Math.round(n * 100) / 100; };

  // ---- inputs -------------------------------------------------------------
  const reviewer = clean(data.reviewer);
  const quote = clean(data.quote || data.text);
  const product = clean(data.product);
  const imageUrl = clean(data.imageUrl);
  if (!quote) throw new Error('The review has no text to quote.');
  if (!reviewer) throw new Error('The review has no reviewer name.');

  const ratingRaw = Number(data.rating);
  if (!Number.isFinite(ratingRaw) || ratingRaw <= 0) {
    throw new Error('The review has no usable Rating (got "' + String(data.rating) + '"). Use a number 1-5.');
  }
  // Honest stars: round to the nearest whole star, never above 5, never below 1.
  const rating = Math.min(5, Math.max(1, ratingRaw));
  const starsFilled = Math.min(5, Math.max(1, Math.round(rating)));
  const ratingLabel = (Math.round(rating * 10) / 10).toFixed(1) + ' out of 5';

  // ---- brand knobs --------------------------------------------------------
  const brandName = clean(cfg.brandName) || 'Your brand';
  const kicker = (clean(cfg.brandKicker) || 'CUSTOMER LOVE').toUpperCase();
  const verifiedLabel = clean(cfg.verifiedLabel) || 'Verified customer';
  const hookLine = clean(cfg.hookLine) || 'Real words from real customers.';
  const ctaText = clean(cfg.ctaText) || 'Read the reviews';
  const quoteFont = clean(cfg.quoteFont) || 'Playfair Display';
  const uiFont = clean(cfg.uiFont) || 'Outfit';
  const paper = clean(cfg.paperColor) || '#F5EDE6';
  const ink = clean(cfg.inkColor) || '#1C1512';
  const accent = clean(cfg.accentColor) || '#C2553D';
  const star = clean(cfg.starColor) || '#E0A33C';
  const mutedOnInk = clean(cfg.mutedOnInk) || '#CFBAAE';
  const mutedOnPaper = clean(cfg.mutedOnPaper) || '#70594D';

  // storeUrl -> bare host, so the CTA card never shows a raw https:// prefix.
  const storeRaw = clean(cfg.storeUrl);
  const storeDomain = storeRaw
    .replace(/^[a-zA-Z][a-zA-Z0-9+.-]*:\/\//, '')
    .replace(/^www\./, '')
    .split('/')[0]
    .replace(/[?#].*$/, '');

  // ---- colour helpers -----------------------------------------------------
  const hexToRgb = function (hex) {
    let h = String(hex).trim().replace('#', '');
    if (h.length === 3) h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
    const n = parseInt(h, 16);
    if (!Number.isFinite(n) || h.length !== 6) return { r: 194, g: 85, b: 61 };
    return { r: (n >> 16) & 255, g: (n >> 8) & 255, b: n & 255 };
  };
  const rgba = function (hex, a) {
    const c = hexToRgb(hex);
    return 'rgba(' + c.r + ',' + c.g + ',' + c.b + ',' + a + ')';
  };
  const hx = function (v) { return ('0' + Math.max(0, Math.min(255, Math.round(v))).toString(16)).slice(-2); };
  const lighten = function (hex, t) {
    const c = hexToRgb(hex);
    const f = function (v) { return v + (255 - v) * t; };
    return '#' + hx(f(c.r)) + hx(f(c.g)) + hx(f(c.b));
  };
  const darken = function (hex, t) {
    const c = hexToRgb(hex);
    return '#' + hx(c.r * (1 - t)) + hx(c.g * (1 - t)) + hx(c.b * (1 - t));
  };
  // Flatten `over` at opacity `a` onto `base` — the same maths the renderer
  // does when a translucent bloom is painted over the field.
  const flatten = function (base, over, a) {
    const b = hexToRgb(base);
    const o = hexToRgb(over);
    return '#' + hx(b.r + (o.r - b.r) * a) + hx(b.g + (o.g - b.g) * a) + hx(b.b + (o.b - b.b) * a);
  };

  // ---- contrast guard -----------------------------------------------------
  // The platform's own contrast lint compares `style.color` with the SCENE's
  // flat backgroundColor — it cannot see the radial fields these scenes paint,
  // so a tone that "passes" the lint can still land at 2.7:1 on the lit part of
  // a gradient. The builder therefore measures every secondary tone against the
  // BRIGHTEST pixel its field can reach and lifts it until it clears WCAG AA,
  // whatever brand colours the importer sets.
  const AA = 4.5;
  const relLum = function (hex) {
    const c = hexToRgb(hex);
    const ch = function (v) {
      const s = v / 255;
      return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4);
    };
    return 0.2126 * ch(c.r) + 0.7152 * ch(c.g) + 0.0722 * ch(c.b);
  };
  const contrast = function (a, b) {
    const la = relLum(a);
    const lb = relLum(b);
    return (Math.max(la, lb) + 0.05) / (Math.min(la, lb) + 0.05);
  };
  // Walks the colour away from the background (lighter on dark fields, darker
  // on light ones) in 4% steps until the ratio is met.
  const ensureContrast = function (fg, bg, min) {
    if (contrast(fg, bg) >= min) return fg;
    const up = relLum(fg) >= relLum(bg);
    for (let t = 0.04; t <= 1.0001; t += 0.04) {
      const c = up ? lighten(fg, t) : darken(fg, t);
      if (contrast(c, bg) >= min) return c;
    }
    return up ? '#FFFFFF' : '#000000';
  };

  // ---- the two fields, and the tones that have to survive them ------------
  // FIELD_LIFT is how far the dark scenes lift at their centre; the blooms are
  // the soft glows stacked on top. Keeping these low is half the contrast fix —
  // the other half is lifting the type.
  const FIELD_LIFT = 0.14;
  const HALO_PEAK = 0.18;
  const BLOOM_PEAK = 0.16;
  const PAPER_BLOOM = 0.16;
  const fieldTop = lighten(ink, FIELD_LIFT);
  const darkPeakStar = flatten(fieldTop, star, HALO_PEAK);
  const darkPeakAccent = flatten(fieldTop, accent, BLOOM_PEAK);
  const darkPeak = relLum(darkPeakStar) >= relLum(darkPeakAccent) ? darkPeakStar : darkPeakAccent;
  const paperLow = flatten(paper, accent, PAPER_BLOOM);

  const mutedInk = ensureContrast(mutedOnInk, darkPeak, AA);
  const mutedPaper = ensureContrast(mutedOnPaper, paperLow, AA);
  const kickerInk = ensureContrast(lighten(accent, 0.3), darkPeak, AA);

  // Solid accent surfaces (CTA pill, monogram chip): pick the label colour that
  // already clears AA on the accent, and only push the surface darker when
  // neither paper nor ink does.
  let chipBg = accent;
  let chipText = contrast(paper, accent) >= AA ? paper : ink;
  if (contrast(chipText, chipBg) < AA) {
    chipText = paper;
    chipBg = ensureContrast(accent, paper, AA);
  }
  // The chip's gradient sweep always runs AWAY from the label colour, so every
  // pixel of the chip is at least as readable as its darkest/lightest end.
  const chipEdge = relLum(chipText) > relLum(chipBg) ? darken(chipBg, 0.16) : lighten(chipBg, 0.16);

  // ---- star row -----------------------------------------------------------
  // Five 5-point stars drawn as polygons, so the count is DATA and not a glyph
  // string. Inner/outer radius ratio 0.382 = the classic star proportion.
  const starPoints = function (cx, cy, ro, ri) {
    const pts = [];
    for (let i = 0; i < 10; i += 1) {
      const r = i % 2 === 0 ? ro : ri;
      const a = (Math.PI / 5) * i - Math.PI / 2;
      pts.push(Math.round((cx + r * Math.cos(a)) * 10) / 10 + ',' + Math.round((cy + r * Math.sin(a)) * 10) / 10);
    }
    return pts.join(' ');
  };
  const starRow = function (filled, size, gap, onColor, offColor) {
    const w = 5 * size + 4 * gap;
    let body = '';
    for (let i = 0; i < 5; i += 1) {
      const cx = i * (size + gap) + size / 2;
      const pts = starPoints(cx, size / 2, size * 0.5, size * 0.191);
      body += i < filled
        ? "<polygon points='" + pts + "' fill='" + onColor + "'/>"
        : "<polygon points='" + pts + "' fill='none' stroke='" + offColor + "' stroke-width='" + Math.max(2, Math.round(size * 0.055)) + "' stroke-linejoin='round'/>";
    }
    return {
      w: w,
      h: size,
      svg: "<svg width='" + w + "' height='" + size + "' viewBox='0 0 " + w + " " + size + "' xmlns='http://www.w3.org/2000/svg'>" + body + '</svg>',
    };
  };

  // ---- greedy wrap estimate ----------------------------------------------
  // Calibrated against the rendered source design: Playfair Display italic
  // averages ~0.50em per glyph, the sans UI face ~0.52em.
  const wrapLines = function (text, fontPx, boxPx, avgEm) {
    const perLine = Math.max(6, Math.floor(boxPx / (fontPx * avgEm)));
    let lines = 1;
    let used = 0;
    const words = String(text).split(' ');
    for (let i = 0; i < words.length; i += 1) {
      const w = words[i];
      const need = used === 0 ? w.length : used + 1 + w.length;
      if (need <= perLine) { used = need; continue; }
      lines += 1;
      used = Math.min(w.length, perLine);
    }
    return lines;
  };

  // ---- timing -------------------------------------------------------------
  // A scene `transition` overlaps its two scenes, so every non-last scene
  // stores duration = visible seconds + transitionDuration.
  const TD = 0.5;
  const hookSeconds = 3.8;
  const qLen = quote.length;
  const quoteSeconds = round(Math.min(Math.max(3.6 + qLen * 0.026, 5.4), 8.6));
  const ctaSeconds = 4.2;
  const totalSeconds = round(hookSeconds + quoteSeconds + ctaSeconds);

  const hasImage = /^https?:\/\//i.test(imageUrl);

  // =========================================================================
  // SCENE 1 — hook
  // =========================================================================
  const s1Dur = round(hookSeconds + TD);
  const bigStars = starRow(starsFilled, hasImage ? 112 : 136, hasImage ? 30 : 36, star, rgba(paper, 0.36));

  // A soft-edged accent bloom — hard-edged circles read cheap on a dark field.
  const bloom = function (id, hex, peak) {
    return "<radialGradient id='" + id + "' cx='0.5' cy='0.5' r='0.5'>"
      + "<stop offset='0' stop-color='" + hex + "' stop-opacity='" + peak + "'/>"
      + "<stop offset='0.6' stop-color='" + hex + "' stop-opacity='" + round(peak * 0.45) + "'/>"
      + "<stop offset='1' stop-color='" + hex + "' stop-opacity='0'/></radialGradient>";
  };

  // With a product photo the type block sits in the lower third over a scrim;
  // without one the same block is centred on a designed gradient.
  const kickerY = hasImage ? 1120 : 660;
  const starsY1 = hasImage ? 1206 : 766;
  const ratingY = hasImage ? 1382 : 966;

  const hookBg = hasImage
    ? "<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'>"
      // Heavy top + bottom scrim: customer photos are unpredictable, and the
      // type has to clear 4.5:1 on a white wall as well as on a dark one.
      + "<defs><linearGradient id='rtvScrim' x1='0' y1='0' x2='0' y2='1'>"
      + "<stop offset='0' stop-color='" + ink + "' stop-opacity='0.72'/>"
      + "<stop offset='0.22' stop-color='" + ink + "' stop-opacity='0.3'/>"
      + "<stop offset='0.44' stop-color='" + ink + "' stop-opacity='0.36'/>"
      + "<stop offset='0.56' stop-color='" + ink + "' stop-opacity='0.88'/>"
      + "<stop offset='1' stop-color='" + ink + "' stop-opacity='0.97'/></linearGradient></defs>"
      + "<rect width='1080' height='1920' fill='url(#rtvScrim)'/>"
      + "<rect x='64' y='64' width='952' height='1792' rx='36' fill='none' stroke='" + rgba(paper, 0.22) + "' stroke-width='1.5'/>"
      + '</svg>'
    : "<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'>"
      + "<defs><radialGradient id='rtvHook' cx='0.5' cy='0.34' r='0.94'>"
      + "<stop offset='0' stop-color='" + fieldTop + "'/>"
      + "<stop offset='1' stop-color='" + ink + "'/></radialGradient>"
      + bloom('rtvHookA', accent, BLOOM_PEAK) + bloom('rtvHookB', accent, round(BLOOM_PEAK * 0.66)) + '</defs>'
      + "<rect width='1080' height='1920' fill='url(#rtvHook)'/>"
      + "<circle cx='900' cy='230' r='420' fill='url(#rtvHookA)'/>"
      + "<circle cx='140' cy='1680' r='380' fill='url(#rtvHookB)'/>"
      + "<rect x='64' y='64' width='952' height='1792' rx='36' fill='none' stroke='" + rgba(paper, 0.18) + "' stroke-width='1.5'/>"
      + '</svg>';

  const s1 = {
    id: 'hook',
    duration: s1Dur,
    backgroundColor: ink,
    transition: 'smoothup',
    transitionId: 'quote',
    transitionDuration: TD,
    visuals: [],
  };

  if (hasImage) {
    // Full-bleed only: `resize` is canvas-relative, so this is the one safe way
    // to place a customer photo of unknown aspect without stretching it.
    s1.visuals.push({
      type: 'IMAGE', src: imageUrl, width: 1080, height: 1920,
      position: 'center-center', resize: 'cover', zoom: true, track: 0,
      enterBegin: 0, exitEnd: s1Dur,
    });
  }

  s1.visuals.push({
    type: 'SVG', width: 1080, height: 1920, track: 1, enterBegin: 0, exitEnd: s1Dur,
    svg: hookBg,
  });
  s1.visuals.push({
    type: 'TEXT', x: 540, y: 140, width: 880, anchor: 'top-center', track: 3,
    enterBegin: 0, enterEnd: 0.45, enterAnimation: 'fade', exitEnd: s1Dur,
    style: { fontFamily: uiFont, color: hasImage ? paper : mutedInk },
    html: "<div style=\"text-align:center; color:" + (hasImage ? paper : mutedInk) + "; font-size:26px; font-weight:700; letter-spacing:9px;\">" + esc(brandName.toUpperCase()) + '</div>',
  });
  s1.visuals.push({
    type: 'TEXT', x: 540, y: kickerY, width: 880, anchor: 'top-center', track: 3,
    enterBegin: 0.15, enterEnd: 0.62, enterAnimation: 'smoothdown', exitEnd: s1Dur,
    style: { fontFamily: uiFont, color: kickerInk },
    html: "<div style=\"text-align:center; color:" + kickerInk + "; font-size:30px; font-weight:800; letter-spacing:11px;\">" + esc(kicker) + '</div>',
  });
  s1.visuals.push({
    type: 'SVG', x: 540, y: starsY1, width: bigStars.w, height: bigStars.h, anchor: 'top-center', track: 3,
    enterBegin: 0.35, enterEnd: 0.95, enterAnimation: 'circleopen', exitEnd: s1Dur,
    svg: bigStars.svg,
  });
  s1.visuals.push({
    type: 'TEXT', x: 540, y: ratingY, width: 880, anchor: 'top-center', track: 3,
    enterBegin: 0.85, enterEnd: 1.22, enterAnimation: 'fade', exitEnd: s1Dur,
    style: { fontFamily: uiFont, color: paper },
    html: "<div style=\"text-align:center; color:" + paper + "; font-size:38px; font-weight:600; letter-spacing:4px;\">" + esc(ratingLabel) + '</div>',
  });

  if (hasImage) {
    if (product) {
      s1.visuals.push({
        type: 'TEXT', x: 540, y: ratingY + 90, width: 880, anchor: 'top-center', track: 3,
        enterBegin: 1.15, enterEnd: 1.55, enterAnimation: 'fade', exitEnd: s1Dur,
        style: { fontFamily: uiFont, color: mutedInk },
        html: "<div style=\"text-align:center; color:" + mutedInk + "; font-size:29px; font-weight:600; letter-spacing:5px;\">" + esc(product.toUpperCase()) + '</div>',
      });
    }
  } else {
    s1.visuals.push({
      // `fade`, not `smoothup`: an upward wipe on a two-line serif block shows
      // the second line before the first for a beat, which reads as a glitch.
      type: 'TEXT', x: 540, y: 1098, width: 860, anchor: 'top-center', track: 3,
      enterBegin: 1.0, enterEnd: 1.55, enterAnimation: 'fade', exitEnd: s1Dur,
      style: { fontFamily: quoteFont, color: paper },
      html: "<div style=\"text-align:center; color:" + paper + "; font-size:64px; line-height:1.22; font-weight:600;\">" + esc(hookLine) + '</div>',
    });
  }

  // =========================================================================
  // SCENE 2 — the quote (paper card)
  // =========================================================================
  const s2Dur = round(quoteSeconds + TD);
  const quoteSize = qLen <= 60 ? 84 : qLen <= 100 ? 72 : qLen <= 150 ? 62 : qLen <= 190 ? 54 : 48;
  const quoteBoxW = 840;
  const quoteLines = wrapLines(quote, quoteSize, quoteBoxW, 0.5);
  const quoteBlockH = Math.round(quoteLines * quoteSize * 1.28);

  const headStars = starRow(starsFilled, 40, 11, star, rgba(ink, 0.26));
  const reviewerSize = reviewer.length <= 18 ? 40 : reviewer.length <= 26 ? 35 : 31;
  const metaText = verifiedLabel + (product ? ' · ' + product : '');

  // Centre quote + rule + reviewer as ONE block so short and long quotes both
  // sit balanced under the header row. The wrap estimate errs long by design:
  // over-estimating a line only adds whitespace, under-estimating collides.
  const blockH = quoteBlockH + 48 + 4 + 56 + 104;
  const quoteY = Math.max(430, Math.round(1030 - blockH / 2));
  const ruleY = quoteY + quoteBlockH + 48;
  const reviewerY = ruleY + 56;

  const quoteBg =
    "<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'>"
    + "<defs><linearGradient id='rtvPaper' x1='0' y1='0' x2='0' y2='1'>"
    + "<stop offset='0' stop-color='" + lighten(paper, 0.5) + "'/>"
    + "<stop offset='1' stop-color='" + paper + "'/></linearGradient>"
    + bloom('rtvPaperA', accent, PAPER_BLOOM) + bloom('rtvPaperB', accent, round(PAPER_BLOOM * 0.62)) + '</defs>'
    + "<rect width='1080' height='1920' fill='url(#rtvPaper)'/>"
    + "<circle cx='980' cy='1780' r='400' fill='url(#rtvPaperA)'/>"
    + "<circle cx='100' cy='1840' r='240' fill='url(#rtvPaperB)'/>"
    + "<text x='96' y='" + (quoteY + 110) + "' font-family='Georgia, serif' font-size='400' fill='" + rgba(accent, 0.14) + "'>&#8220;</text>"
    + '</svg>';

  const monoSize = 100;
  const monogram = (reviewer.match(/[\p{L}\p{N}]/u) || ['?'])[0].toUpperCase();

  const s2 = {
    id: 'quote',
    duration: s2Dur,
    backgroundColor: paper,
    transition: 'smoothup',
    transitionId: 'cta',
    transitionDuration: TD,
    visuals: [
      {
        type: 'SVG', width: 1080, height: 1920, track: 0, enterBegin: 0, exitEnd: s2Dur,
        svg: quoteBg,
      },
      {
        // The hook's wordmark is still on screen for the whole TD-long cross
        // dissolve. Bringing this one in at 0 painted the SAME words a second
        // time, offset and in another colour — pure ghosting. The paper header
        // therefore waits until the dissolve has finished (t = TD) and the
        // wordmark simply re-forms in its new home.
        type: 'TEXT', x: 120, y: 150, width: 560, anchor: 'top-left', track: 2,
        enterBegin: TD, enterEnd: TD + 0.4, enterAnimation: 'fade', exitEnd: s2Dur,
        style: { fontFamily: uiFont, color: mutedPaper },
        html: "<div style=\"color:" + mutedPaper + "; font-size:26px; font-weight:700; letter-spacing:9px;\">" + esc(brandName.toUpperCase()) + '</div>',
      },
      {
        type: 'SVG', x: 960, y: 144, width: headStars.w, height: headStars.h, anchor: 'top-right', track: 2,
        enterBegin: TD + 0.12, enterEnd: TD + 0.55, enterAnimation: 'smoothleft', exitEnd: s2Dur,
        svg: headStars.svg,
      },
      {
        // `fade`, never `smoothup`: an upward wipe unmasks the element box from
        // its bottom edge, so a multi-line quote showed its LAST line — the
        // punchline — a third of a second before its first. A quote always
        // wraps, so this block always fades. It also waits for t = TD so no
        // paper-scene type paints while the hook is still cross-dissolving.
        type: 'TEXT', x: 120, y: quoteY, width: quoteBoxW, anchor: 'top-left', track: 3,
        enterBegin: TD, enterEnd: TD + 0.7, enterAnimation: 'fade', exitEnd: s2Dur,
        style: { fontFamily: quoteFont, color: ink },
        html: "<div style=\"color:" + ink + '; font-size:' + quoteSize + "px; line-height:1.28; font-weight:500; font-style:italic;\">&#8220;" + esc(quote) + '&#8221;</div>',
      },
      {
        type: 'SVG', x: 120, y: ruleY, width: 200, height: 4, anchor: 'top-left', track: 2,
        enterBegin: 1.0, enterEnd: 1.4, enterAnimation: 'smoothleft', exitEnd: s2Dur,
        svg: "<svg width='200' height='4' viewBox='0 0 200 4' xmlns='http://www.w3.org/2000/svg'><rect width='200' height='4' rx='2' fill='" + accent + "'/></svg>",
      },
      {
        type: 'SVG', x: 120, y: reviewerY, width: monoSize, height: monoSize, anchor: 'top-left', track: 2,
        enterBegin: 1.15, enterEnd: 1.6, enterAnimation: 'circleopen', exitEnd: s2Dur,
        svg: "<svg width='" + monoSize + "' height='" + monoSize + "' viewBox='0 0 " + monoSize + ' ' + monoSize + "' xmlns='http://www.w3.org/2000/svg'>"
          + "<defs><linearGradient id='rtvMono' x1='0' y1='0' x2='1' y2='1'>"
          + "<stop offset='0' stop-color='" + chipBg + "'/><stop offset='1' stop-color='" + chipEdge + "'/></linearGradient></defs>"
          + "<circle cx='" + monoSize / 2 + "' cy='" + monoSize / 2 + "' r='" + monoSize / 2 + "' fill='url(#rtvMono)'/>"
          + "<text x='" + monoSize / 2 + "' y='" + (monoSize / 2 + 16) + "' font-family='Georgia, serif' font-size='46' font-weight='700' fill='" + chipText + "' text-anchor='middle'>" + esc(monogram) + '</text>'
          + '</svg>',
      },
      {
        type: 'TEXT', x: 252, y: reviewerY + 8, width: 700, anchor: 'top-left', track: 2,
        enterBegin: 1.25, enterEnd: 1.7, enterAnimation: 'smoothleft', exitEnd: s2Dur,
        style: { fontFamily: uiFont, color: ink },
        html: "<div style=\"color:" + ink + '; font-size:' + reviewerSize + "px; font-weight:700;\">" + esc(reviewer) + '</div>'
          + "<div style=\"margin-top:8px; color:" + mutedPaper + "; font-size:25px; font-weight:600;\">" + esc(metaText) + '</div>',
      },
    ],
  };

  // Quiet editorial footer — anchors the bottom of an otherwise airy page.
  if (storeDomain) {
    s2.visuals.push({
      type: 'TEXT', x: 120, y: 1720, width: 840, anchor: 'top-left', track: 2,
      enterBegin: 1.5, enterEnd: 1.9, enterAnimation: 'fade', exitEnd: s2Dur,
      style: { fontFamily: uiFont, color: mutedPaper },
      html: "<div style=\"color:" + mutedPaper + "; font-size:24px; font-weight:600; letter-spacing:5px;\">" + esc(storeDomain.toUpperCase()) + '</div>',
    });
  }

  // =========================================================================
  // SCENE 3 — CTA
  // =========================================================================
  const headline = product || hookLine;
  const headSize = headline.length <= 22 ? 82 : headline.length <= 34 ? 70 : headline.length <= 50 ? 60 : 52;
  const headLines = wrapLines(headline, headSize, 880, 0.52);
  const headH = Math.round(headLines * headSize * 1.16);
  const ctaStars = starRow(starsFilled, 52, 16, star, rgba(paper, 0.32));

  const BRAND_H = 34;
  const PILL_H = 92;
  const DOMAIN_H = 36;
  const blockH3 = ctaStars.h + 78 + headH + 44 + BRAND_H + 92 + PILL_H + (storeDomain ? 56 + DOMAIN_H : 0);
  const starsY3 = Math.max(340, Math.round(960 - blockH3 / 2));
  const headY = starsY3 + ctaStars.h + 78;
  const brandY = headY + headH + 44;
  const pillY = brandY + BRAND_H + 92;
  const domainY = pillY + PILL_H + 56;
  const ringCy = starsY3 + Math.round(ctaStars.h / 2);

  // A soft halo behind the stars instead of hairline rings: rings of any radius
  // that clear the star row also cut straight through the headline below it.
  const ctaBg =
    "<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'>"
    + "<defs><radialGradient id='rtvCta' cx='0.5' cy='0.5' r='0.95'>"
    + "<stop offset='0' stop-color='" + fieldTop + "'/>"
    + "<stop offset='1' stop-color='" + ink + "'/></radialGradient>"
    + bloom('rtvCtaHalo', star, HALO_PEAK) + bloom('rtvCtaB', accent, BLOOM_PEAK) + '</defs>'
    + "<rect width='1080' height='1920' fill='url(#rtvCta)'/>"
    + "<circle cx='540' cy='" + ringCy + "' r='300' fill='url(#rtvCtaHalo)'/>"
    + "<circle cx='900' cy='1780' r='420' fill='url(#rtvCtaB)'/>"
    + "<rect x='64' y='64' width='952' height='1792' rx='36' fill='none' stroke='" + rgba(paper, 0.16) + "' stroke-width='1.5'/>"
    + '</svg>';

  const s3 = {
    id: 'cta',
    duration: ctaSeconds,
    backgroundColor: ink,
    visuals: [
      {
        type: 'SVG', width: 1080, height: 1920, track: 0, enterBegin: 0, exitEnd: ctaSeconds,
        svg: ctaBg,
      },
      {
        type: 'SVG', x: 540, y: starsY3, width: ctaStars.w, height: ctaStars.h, anchor: 'top-center', track: 2,
        enterBegin: 0.15, enterEnd: 0.6, enterAnimation: 'fade', exitEnd: ctaSeconds,
        svg: ctaStars.svg,
      },
      {
        // Same wipe trap as the quote: a two-line product name unmasked from the
        // bottom spelled out its tail ("Long Sleeve") on its own for ~0.3 s.
        // One-line headlines keep the upward move; wrapped ones fade.
        type: 'TEXT', x: 540, y: headY, width: 880, anchor: 'top-center', track: 2,
        enterBegin: 0.35, enterEnd: 0.92, enterAnimation: headLines > 1 ? 'fade' : 'smoothup', exitEnd: ctaSeconds,
        style: { fontFamily: quoteFont, color: paper },
        html: "<div style=\"text-align:center; color:" + paper + '; font-size:' + headSize + "px; line-height:1.16; font-weight:600;\">" + esc(headline) + '</div>',
      },
      {
        type: 'TEXT', x: 540, y: brandY, width: 880, anchor: 'top-center', track: 2,
        enterBegin: 0.7, enterEnd: 1.05, enterAnimation: 'fade', exitEnd: ctaSeconds,
        style: { fontFamily: uiFont, color: mutedInk },
        html: "<div style=\"text-align:center; color:" + mutedInk + "; font-size:28px; font-weight:600; letter-spacing:7px;\">" + esc(brandName.toUpperCase()) + '</div>',
      },
      {
        // No `width` on purpose: the renderer sizes a width-less text box to
        // fit-content, and that is what centres an inline-block pill on x=540.
        type: 'TEXT', x: 540, y: pillY, anchor: 'top-center', track: 2,
        enterBegin: 0.95, enterEnd: 1.45, enterAnimation: 'circleopen', exitEnd: ctaSeconds,
        style: { fontFamily: uiFont, color: chipText },
        html: "<div style=\"display:inline-block; background:" + chipBg + '; color:' + chipText + "; border-radius:999px; padding:26px 62px; font-size:38px; font-weight:700;\">" + esc(ctaText) + '</div>',
      },
    ],
  };

  if (storeDomain) {
    s3.visuals.push({
      // The domain is the conversion element on the terminal card — it gets the
      // full-strength paper tone, not the secondary one.
      type: 'TEXT', x: 540, y: domainY, width: 880, anchor: 'top-center', track: 2,
      enterBegin: 1.3, enterEnd: 1.68, enterAnimation: 'fade', exitEnd: ctaSeconds,
      style: { fontFamily: uiFont, color: paper },
      html: "<div style=\"text-align:center; color:" + paper + "; font-size:29px; font-weight:600; letter-spacing:3px;\">" + esc(storeDomain) + '</div>',
    });
  }

  // ---- payload ------------------------------------------------------------
  // The render API only allows letters, digits, spaces, _ and - in `name`.
  const safeName = ('review-' + (product || brandName) + '-' + reviewer)
    .toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60).replace(/-+$/, '');

  const payload = {
    name: safeName || 'customer-review',
    resolution: 'instagram-reel',
    frameRate: 30,
    backgroundColor: ink,
    outputFormat: 'mp4',
    scenes: [s1, s2, s3],
  };

  // NOTE: no `track` here — the render API rejects audios[].track.
  const musicUrl = clean(data.musicUrl);
  if (musicUrl) {
    payload.audios = [{ src: musicUrl, volume: Number(cfg.musicVolume == null ? 0.14 : cfg.musicVolume) }];
  }

  return {
    payload: payload,
    meta: {
      reviewer: reviewer,
      rating: rating,
      starsFilled: starsFilled,
      ratingLabel: ratingLabel,
      product: product || null,
      hasImage: hasImage,
      quoteChars: qLen,
      quoteSize: quoteSize,
      quoteLines: quoteLines,
      quote: quote,
      hookSeconds: hookSeconds,
      quoteSeconds: quoteSeconds,
      ctaSeconds: ctaSeconds,
      totalSeconds: totalSeconds,
      musicUrl: musicUrl || null,
      storeDomain: storeDomain || null,
      // Resolved tones + the ratios they hold on the worst pixel of each field,
      // so a run can be contrast-audited from its own output.
      contrast: {
        darkPeak: darkPeak,
        paperLow: paperLow,
        mutedOnInk: mutedInk + ' ' + (Math.round(contrast(mutedInk, darkPeak) * 100) / 100) + ':1',
        kicker: kickerInk + ' ' + (Math.round(contrast(kickerInk, darkPeak) * 100) / 100) + ':1',
        mutedOnPaper: mutedPaper + ' ' + (Math.round(contrast(mutedPaper, paperLow) * 100) / 100) + ':1',
        chip: chipText + ' on ' + chipBg + ' ' + (Math.round(contrast(chipText, chipBg) * 100) / 100) + ':1',
      },
    },
  };
}

// === n8n glue ===
const config = $('Config').first().json;
const row = $input.first().json;
const built = buildProject(config, {
  reviewer: row.reviewer,
  rating: row.rating,
  text: row.text,
  quote: row.quote,
  product: row.product,
  imageUrl: row.imageUrl,
  musicUrl: row.musicUrl,
});
built.meta.rowNumber = row.rowNumber == null ? null : row.rowNumber;
built.meta.source = row.source || 'sheet';
built.meta.trimmedBy = row.trimmedBy || 'rule';
built.meta.originalChars = row.originalChars == null ? built.meta.quoteChars : row.originalChars;
built.meta.musicSkippedReason = row.musicSkippedReason || null;
built.meta.reviewId = row.reviewId == null ? null : row.reviewId;
return [{ json: built }];

// The free validate endpoint runs the exact pipeline a render submission runs,
// so a failure here is a payload bug - surface the field list instead of a
// generic HTTP error.
const res = $input.first().json;
const status = res.statusCode ?? (res.valid === true ? 200 : 400);
const body = res.body || { ...res, details: res.errors ?? res.details };

if (status !== 200) {
  const details = Array.isArray(body.details)
    ? body.details.map((d) => '  - ' + d.field + ': ' + d.message).join('\n')
    : JSON.stringify(body).slice(0, 500);
  throw new Error('Zvid rejected the project (HTTP ' + status + '): ' + (body.message || body.error) + '\n' + details);
}

const build = $('Build project JSON').first().json;
return [{
  json: {
    ...build,
    creditsRequired: body.creditsRequired,
    warnings: body.warnings || [],
    schemaVersion: body.schemaVersion,
  },
}];

// Dry run: everything except the paid render. Open editorLink to preview the
// exact video, then set dryRun to false in Config to go live. The sheet row is
// NOT marked done on a dry run, so the next real run picks the same review.
const cfg = $('Config').first().json;
const d = $('Check validation').first().json;

// The draft save is best-effort (onError: continue) so a hiccup there never
// hides the rest of the dry-run report.
let editorLink = null;
let draftId = null;
try {
  const project = $('Save draft to editor').first().json.project;
  if (project && project.id) {
    draftId = project.id;
    editorLink = String(cfg.editorUrl || 'https://editor.zvid.io').replace(/\/+$/, '') + '/?project=' + project.id;
  }
} catch (e) { /* draft step skipped or failed */ }

return [{
  json: {
    dryRun: true,
    reviewer: d.meta.reviewer,
    rating: d.meta.rating,
    stars: d.meta.starsFilled,
    quote: d.meta.quote,
    quoteChars: d.meta.quoteChars,
    trimmedBy: d.meta.trimmedBy,
    product: d.meta.product,
    sheetRow: d.meta.rowNumber,
    editorLink,
    draftId,
    creditsRequired: d.creditsRequired,
    videoSeconds: d.meta.totalSeconds,
    warnings: d.warnings,
    sheetUpdated: false,
    nextStep: editorLink
      ? 'Open editorLink to preview the draft, then set dryRun to false in Config to render and mark the row done.'
      : 'Set dryRun to false in Config to render this for real.',
    payload: d.payload,
  },
}];

// Fails fast on a failed render and stops the poll loop from running forever.
const cfg = $('Config').first().json;
const job = $input.first().json;

if (job.state === 'failed') {
  throw new Error('Render failed: ' + (job.failedReason || 'no reason given'));
}

const maxPolls = Math.ceil((Number(cfg.timeoutMinutes || 20) * 60) / Number(cfg.pollSeconds || 10));
if ($runIndex + 1 >= maxPolls) {
  throw new Error('Render did not finish within ' + cfg.timeoutMinutes + ' minutes (job ' + job.id + ', state ' + job.state + ').');
}

return $input.all();

// Final report for a live run. In sheet mode the row is already marked done by
// this point; in Judge.me mode the review id is remembered HERE - only after a
// successful render - so a failed render retries the same review next time.
const cfg = $('Config').first().json;
const build = $('Check validation').first().json;
const job = $('Get render status').first().json;
const url = typeof job.result === 'string' ? job.result : (job.result ? job.result.url : null);

const source = String(cfg.source || 'sheet').trim().toLowerCase();
if (source === 'judgeme' && build.meta.reviewId) {
  const staticData = $getWorkflowStaticData('global');
  const seen = Array.isArray(staticData.seenReviewIds) ? staticData.seenReviewIds : [];
  staticData.seenReviewIds = [String(build.meta.reviewId)].concat(seen.filter((id) => id !== String(build.meta.reviewId))).slice(0, 200);
}

return [{
  json: {
    rendered: true,
    videoUrl: url,
    jobId: job.id,
    source,
    reviewer: build.meta.reviewer,
    rating: build.meta.rating,
    stars: build.meta.starsFilled,
    product: build.meta.product,
    quote: build.meta.quote,
    quoteChars: build.meta.quoteChars,
    originalChars: build.meta.originalChars,
    trimmedBy: build.meta.trimmedBy,
    hadProductImage: build.meta.hasImage,
    music: build.meta.musicUrl ? "on" : ("off - " + (build.meta.musicSkippedReason || "no musicUrl")),
    videoSeconds: build.meta.totalSeconds,
    creditsCharged: build.creditsRequired,
    sheetRow: build.meta.rowNumber,
    sheetStatus: source === 'sheet' ? cfg.statusDoneValue : null,
    reviewId: build.meta.reviewId,
  },
}];
